  reads:['PQr: QUESTIONSET_HIERARCHY, ASSESSMENT_DATA_RAW (userAssessmentRaw), OLD_ASSESSMENT','PQ: ALL_COURSE_PROGRAM_COMPUTED, USER_ORG_COMPUTED_FILE'],
  joins:['LEFT · old-assessment ⋈ course on courseID','LEFT · + user-org on userID','LEFT · assessment ⋈ org on assessOrgID','LEFT · df ⋈ hierarchy on identifier (shared add_hierarchy_column helper — reused by 3+ report jobs)','INNER · user-attempt ⋈ assessment-children on assessChildID','LEFT · + assessment details on assessID','LEFT · + course details on courseID','LEFT · + user-org on userID','LEFT · course ⋈ rating on (courseID, categoryLower)','LEFT · course ⋈ org on courseOrgID','INNER · section-wise results ⋈ questionset hierarchy on assessChildID=questionsetID','LEFT · raw attempts ⋈ section-derived results on (assessChildID, userID, assessStartTimestamp) — deliberately LEFT not INNER, to keep every raw attempt even where section logic doesn\'t apply'],
  proc:['Section-level cutoff: pass requires every section to pass. Overall-result cutoff: pass requires the overall score ≥ the configured minimum','Writes its output back into the RAW cache directory (userAssessment) rather than the computed/ dir — a deliberate "clean the raw cache in place" step'],
  writes:{ parquet:['ALL_ASSESSMENT_COMPUTED, OLD_ASSESSMENT_COMPUTED', 'raw cache: userAssessment (cleaned)'] },
